changes.body:
match store.find_user(username) {
    Some(user) if !user.locked && verify_password(password, &user.password_hash) => {
        AuthResult::Authenticated {
            username: user.username,
        }
    }
    _ => AuthResult::InvalidCredentials,
}

// Always run exactly one Argon2 verification so every failure path costs the same time.
let user = store.find_user(username);
let hash = match &user {
    Some(u) => u.password_hash.as_str(),
    None => dummy_password_hash(),
};
let password_ok = verify_password(password, hash);
match user {
    Some(user) if password_ok && !user.locked => AuthResult::Authenticated {
        username: user.username,
    },
    _ => AuthResult::InvalidCredentials,
}

